marks={(0,7),(2,3),(2,7),(2,9),(4,1),(4,2),(5,7),(6,5),(7,5),(11,8),(13,0),(13,8),(14,4),(15,1),(15,4),(15,10),(17,0),(20,3),(20,4),(20,9),(21,5),(21,7),(22,1),(23,3),(23,7),(27,5),(27,9)}
g=[ [1]*11 for _ in range(28)]
for r,c in marks:g[r][c]=7
# Connect successive markers per row/column in color 3
for r in range(28):
 cs=sorted(c for rr,c in marks if rr==r)
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):g[r][c]=3
for c in range(11):
 rs=sorted(r for r,cc in marks if cc==c)
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):g[r][c]=3
print(g)
print('\n'.join(' '.join(map(str,row)) for row in g))
